INSERT OR REPLACE INTO dm_messages (id, user_a, user_b, frm, msg_type, text, media, ts, created_at, updated_at) VALUES
('ea1321f0aab9', 'baris', 'baris', 'baris', 'text', 'merhaba', NULL, 1781699712, 1781699712, 1781699712),
('f19d5646e661', 'demo_elif', 'u54c58ec41b54', 'demo_elif', 'text', 'Selam! Bugünkü bisiklet rotanı gördüm, süperdi 🚴', NULL, 1782825311, 1782825311, 1782825311),
('fd4318a6664c', 'demo_elif', 'u54c58ec41b54', 'u54c58ec41b54', 'text', 'Sağ ol! Sahil boyu 18 km sürdüm, hava harikaydı', NULL, 1782827253, 1782827253, 1782827253),
('62a439a856a4', 'demo_elif', 'u54c58ec41b54', 'demo_elif', 'text', 'Videosunu da oluşturdun mu? 3D olanı çok güzel oluyor', NULL, 1782830065, 1782830065, 1782830065),
('c3af7d8c0cdf', 'demo_elif', 'u54c58ec41b54', 'u54c58ec41b54', 'text', 'Evet otomatik oluştu, birazdan atarım sana', NULL, 1782832625, 1782832625, 1782832625),
('648f106382c1', 'demo_elif', 'u54c58ec41b54', 'demo_elif', 'text', 'Harika, yarın birlikte gidelim mi?', NULL, 1782835037, 1782835037, 1782835037),
('ae01ba5f72f5', 'demo_elif', 'u54c58ec41b54', 'u54c58ec41b54', 'text', 'Olur, sabah 9 gibi buluşalım', NULL, 1782838657, 1782838657, 1782838657),
('52b7c3c057e6', 'demo_elif', 'u54c58ec41b54', 'demo_elif', 'text', 'Tamamdır, konumumu paylaşırım 👍', NULL, 1782840443, 1782840443, 1782840443),
('58bc617bcc39', 'demo_mert', 'u54c58ec41b54', 'demo_mert', 'text', 'Kanka motor turu ne zaman?', NULL, 1782825311, 1782825311, 1782825311),
('b5112036e541', 'demo_mert', 'u54c58ec41b54', 'u54c58ec41b54', 'text', 'Cumartesi düşünüyorum, sen varsın değil mi?', NULL, 1782826714, 1782826714, 1782826714),
('8f9dd66c142c', 'demo_mert', 'u54c58ec41b54', 'demo_mert', 'text', 'Kesin varım! Geçen sürüşünün rota filmi efsaneydi', NULL, 1782828392, 1782828392, 1782828392),
('3a2a9b2d5948', 'demo_mert', 'u54c58ec41b54', 'u54c58ec41b54', 'text', 'Bu sefer dağ yolundan gidelim, manzara müthiş', NULL, 1782830151, 1782830151, 1782830151),
('7de64b39ee83', 'demo_mert', 'u54c58ec41b54', 'demo_mert', 'text', 'Süper, canlı konumu açık tut ki takip edeyim', NULL, 1782831578, 1782831578, 1782831578),
('bf99237e73f1', 'demo_mert', 'u54c58ec41b54', 'u54c58ec41b54', 'text', 'Tabii, uygulamadan görürsün', NULL, 1782835449, 1782835449, 1782835449),
('47c69bad496a', 'demo_mert', 'u54c58ec41b54', 'demo_mert', 'text', '👍 Görüşürüz', NULL, 1782837710, 1782837710, 1782837710),
('1c70828d1aec', 'demo_zeynep', 'u54c58ec41b54', 'demo_zeynep', 'text', 'Bu sabah koşuya çıktın mı?', NULL, 1782825311, 1782825311, 1782825311),
('3df17c3efd93', 'demo_zeynep', 'u54c58ec41b54', 'u54c58ec41b54', 'text', 'Evet 5 km koştum, tempom düzeliyor 🏃', NULL, 1782828290, 1782828290, 1782828290),
('e18f512b6fc2', 'demo_zeynep', 'u54c58ec41b54', 'demo_zeynep', 'text', 'Aferin! Haftalık özet videon geldi mi?', NULL, 1782830940, 1782830940, 1782830940),
('5c3808b4c3d5', 'demo_zeynep', 'u54c58ec41b54', 'u54c58ec41b54', 'text', 'Geldi, tüm haftanın rotalarını birleştirmiş çok güzel', NULL, 1782833371, 1782833371, 1782833371),
('20722a69001f', 'demo_zeynep', 'u54c58ec41b54', 'demo_zeynep', 'text', 'Ben de premium aldım, otomatik video çok pratik', NULL, 1782836232, 1782836232, 1782836232),
('b387f2a84a07', 'demo_zeynep', 'u54c58ec41b54', 'u54c58ec41b54', 'text', 'Kesinlikle, hiç uğraşmadan oluşuyor', NULL, 1782837270, 1782837270, 1782837270),
('f24c624ae179', 'demo_zeynep', 'u54c58ec41b54', 'demo_zeynep', 'text', 'Yarın parkta buluşalım mı?', NULL, 1782840211, 1782840211, 1782840211),
('853c1064f6e5', 'demo_zeynep', 'u54c58ec41b54', 'u54c58ec41b54', 'text', 'Olur, konum atarım 📍', NULL, 1782843414, 1782843414, 1782843414),
('e45a18f2eb8f', 'appreview', 'demo_elif', 'demo_elif', 'text', 'Hey! Are you joining the morning ride tomorrow? 🚴', NULL, 1782367013, 1782367013, 1782367013),
('50651a6f9a1b', 'appreview', 'demo_elif', 'appreview', 'text', 'Definitely! What time are we meeting?', NULL, 1782367313, 1782367313, 1782367313),
('fc3d9acdf4f7', 'appreview', 'demo_elif', 'demo_elif', 'text', '7 AM at the park entrance. I''ll share my live location so you can find me 📍', NULL, 1782367493, 1782367493, 1782367493),
('433ba704c984', 'appreview', 'demo_elif', 'appreview', 'text', 'Perfect, see you there 👍', NULL, 1782367613, 1782367613, 1782367613),
('117234778342', 'appreview', 'demo_elif', 'demo_elif', 'text', 'Just finished a 24 km route, the video came out great 🔥', NULL, 1782375713, 1782375713, 1782375713),
('1baee569b45a', 'appreview', 'demo_elif', 'appreview', 'text', 'Nice! Send it over 😎', NULL, 1782375893, 1782375893, 1782375893),
('1ae65af0506a', 'appreview', 'demo_mert', 'demo_mert', 'text', 'That coastal motorcycle ride yesterday was amazing 🏍️', NULL, 1782345413, 1782345413, 1782345413),
('8c97a48658a7', 'appreview', 'demo_mert', 'appreview', 'text', 'Right? The auto route video looks so cinematic', NULL, 1782345653, 1782345653, 1782345653),
('0611ae59a74d', 'appreview', 'demo_mert', 'demo_mert', 'text', 'Mine is still rendering, send me yours when it''s ready', NULL, 1782346013, 1782346013, 1782346013),
('5124b0c9e985', 'appreview', 'demo_mert', 'appreview', 'text', 'Sure, I''ll share it from the ride screen 🎬', NULL, 1782346133, 1782346133, 1782346133),
('9be13018378c', 'appreview', 'demo_mert', 'demo_mert', 'text', 'Thanks! Heart rate overlay is a nice touch 💓', NULL, 1782377213, 1782377213, 1782377213),
('8c049d847ab3', 'appreview', 'demo_zeynep', 'demo_zeynep', 'text', 'New personal best on my 5K run today! 🏃‍♀️', NULL, 1782291413, 1782291413, 1782291413),
('5f0d058e1351', 'appreview', 'demo_zeynep', 'appreview', 'text', 'Wow, congrats! 🎉', NULL, 1782291713, 1782291713, 1782291713),
('103f8f583a1a', 'appreview', 'demo_zeynep', 'demo_zeynep', 'text', 'Thanks 🙏 Following your live location helped me keep pace', NULL, 1782292013, 1782292013, 1782292013),
('5f20dd4fb4d7', 'appreview', 'demo_zeynep', 'appreview', 'text', 'Anytime! Let''s do the long run this weekend', NULL, 1782292193, 1782292193, 1782292193),
('32f9f2fc20a8', 'u5f41b66429bc', 'u69be3f7e960e', 'u5f41b66429bc', 'text', '🤗', NULL, 1784132127, 1784132127, 1784132127),
